using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
namespace ClearSpace {
public static class RuleCompiler {
 public static List<Rule> Resolve(LoadedRulePack pack,DiscoveryResult discovery,CancellationToken token=default(CancellationToken)){RulePackValidator.Validate(pack.Pack);var rules=new List<Rule>();foreach(var definition in pack.Pack.Rules){token.ThrowIfCancellationRequested();var apps=(discovery??new DiscoveryResult()).Applications.Where(a=>RuleStore.MatchesDefinition(definition,a)).Take(100).ToList();if(apps.Count==0)continue;var roots=new List<string>();var exclusions=new List<string>();foreach(var app in apps){token.ThrowIfCancellationRequested();foreach(string path in definition.Paths)roots.AddRange(PathPolicy.Resolve(path,app,true,token));foreach(string path in definition.ExcludePaths??new string[0])exclusions.AddRange(PathPolicy.Resolve(path,app,false,token));}roots=roots.Where(p=>Directory.Exists(p)&&PathPolicy.AllowedCacheRoot(p)).Distinct(StringComparer.OrdinalIgnoreCase).Take(100).ToList();if(roots.Count==0)continue;var owners=apps.Select(a=>Path.GetFileNameWithoutExtension(a.Executable)).Where(s=>!String.IsNullOrEmpty(s)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();var rule=new Rule("library-"+(String.IsNullOrEmpty(pack.Pack.PackId)?"":pack.Pack.PackId+"-")+definition.Id,definition.Name+" "+definition.Part,definition.Group,definition.Description??"外部路径规则",definition.Impact??"需自行确认缓存用途",roots.ToArray(),Math.Max(definition.KeepDays,definition.Conditions==null?0:definition.Conditions.MinAgeDays),false,owners){Software=definition.Name,Part=definition.Part??"规则库缓存",GroupOverride=definition.Group,AllowManual=pack.Pack.Schema==1,ForceBackup=true,Source=String.IsNullOrEmpty(pack.Pack.Name)?"JSON":pack.Pack.Name,Conditions=definition.Conditions,Extensions=definition.Extensions,ExcludedRoots=exclusions.ToArray(),ExcludedNames=(definition.ExcludeNames??new string[0]).Concat(PathPolicy.SensitiveNames).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),FileNameRegex=definition.FileNameRegex,Detection="规则库 "+pack.Pack.Version+" · "+pack.Trust+"\n"+RuleConditionEvaluator.Describe(definition)+"\n"+String.Join("\n",apps.Take(3).Select(RuleStore.Describe))};rules.Add(rule);}return rules;}
}
}
